class HitCounter {
  constructor() {
    this.hits = []
    this.head = 0
  }

  hit(t) {
    this.hits.push(t)
  }

  count(t) {
    while (this.head < this.hits.length && this.hits[this.head] <= t - 300) this.head++
    return this.hits.length - this.head
  }
}

function runHitCounter(ops) {
  const counter = new HitCounter()
  return ops.map(([op, t]) => (op === 'hit' ? (counter.hit(t), null) : counter.count(t)))
}

solution.py:
from collections import deque


class HitCounter:
    def __init__(self):
        self.hits = deque()

    def hit(self, t):
        self.hits.append(t)

    def count(self, t):
        while self.hits and self.hits[0] <= t - 300:
            self.hits.popleft()
        return len(self.hits)


def run_hit_counter(ops):
    counter = HitCounter()
    out = []
    for op, t in ops:
        if op == "hit":
            counter.hit(t)
            out.append(None)
        else:
            out.append(counter.count(t))
    return out
